];

const theme = createTheme({
  palette: {
    primary: {
      main: '#FF0000', // YouTube red
    },
    secondary: {
      main: '#282828', // YouTube dark gray
    },
    background: {
      default: '#F9F9F9', // YouTube light gray background
      paper: '#FFFFFF',
    },
  },
  typography: {
    fontFamily: [
      'Roboto',
      'Arial',
      'sans-serif',
    ].join(','),
  },
});

const drawerWidth = 240;

function App() {
  const [videos, setVideos] = useState(sampleVideos);
  const [selectedVideo, setSelectedVideo] = useState(null);
  const [summary, setSummary] = useState(null);
  const [notes, setNotes] = useState(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState('summary');
  const [searchQuery, setSearchQuery] = useState('');
  const [showSummaryPanel, setShowSummaryPanel] = useState(false);

  const handleVideoSelect = (video) => {
    setSelectedVideo(video);
    setShowSummaryPanel(false); // Reset summary panel when selecting a new video
    setSummary(null);
    setNotes(null);
  };

  const handleSearch = (query) => {
    setSearchQuery(query);
    // In a real app, this would call an API to search for videos
    // For now, we'll just filter our sample videos
    if (query) {
      const filteredVideos = sampleVideos.filter(video => 
        video.title.toLowerCase().includes(query.toLowerCase())
      );
      setVideos(filteredVideos);
    } else {
      setVideos(sampleVideos);
    }
  };

  const generateSummary = async () => {
    if (!selectedVideo) return;

    setLoading(true);
    setShowSummaryPanel(true);
    setSummary(null);
    setNotes(null);

    try {
      // Step 1: Get transcript
      const transcriptResponse = await fetch('/api/transcript', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ videoId: selectedVideo.id }),
      });

      const transcriptData = await transcriptResponse.json();

      if (!transcriptData.success) {
        throw new Error(transcriptData.error || 'Failed to fetch transcript');
      }

      const { transcript } = transcriptData;

      // Step 2: Generate summary
      const summaryResponse = await fetch('/api/summary', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ transcript }),
      });

      const summaryData = await summaryResponse.json();

      if (!summaryData.success) {
        throw new Error(summaryData.error || 'Failed to generate summary');
      }

      setSummary(summaryData.summary);

      // Step 3: Generate notes
      const notesResponse = await fetch('/api/notes', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ transcript }),
      });

      const notesData = await notesResponse.json();

      if (!notesData.success) {
        throw new Error(notesData.error || 'Failed to generate notes');
      }

      setNotes(notesData.notes);

    } catch (error) {
      console.error('Error processing video:', error);
      alert(`Error: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };

  const handleTimeClick = (time) => {
    // Find the video player iframe and set its current time
    const iframe = document.querySelector('iframe');
    if (iframe && iframe.contentWindow) {
      // Convert timestamp format (e.g., "1:30") to seconds
      const timeParts = time.split(':');
      let seconds = 0;

      if (timeParts.length === 2) {
        // Minutes:Seconds format
        seconds = parseInt(timeParts[0]) * 60 + parseInt(timeParts[1]);
      } else if (timeParts.length === 3) {
        // Hours:Minutes:Seconds format
        seconds = parseInt(timeParts[0]) * 3600 + parseInt(timeParts[1]) * 60 + parseInt(timeParts[2]);
      }

      // Use YouTube iframe API to seek to the specified time
      iframe.contentWindow.postMessage(JSON.stringify({
        event: 'command',
        func: 'seekTo',
        args: [seconds, true]
      }), '*');
    }
  };

  // For demo purposes, select the first video by default
  useEffect(() => {
    if (videos.length > 0 && !selectedVideo) {
      setSelectedVideo(videos[0]);
    }
  }, [videos, selectedVideo]);

  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Box sx={{ display: 'flex', flexDirection: 'column', height: '100vh' }}>
        <Header onSearch={handleSearch} onGenerateSummary={generateSummary} showSummaryButton={!!selectedVideo} />

        <Box sx={{ display: 'flex', flex: 1, overflow: 'hidden' }}>
          {/* Sidebar */}
          <Drawer
            variant="permanent"
            sx={{
              width: drawerWidth,
              flexShrink: 0,
              '& .MuiDrawer-paper': {
                width: drawerWidth,
                boxSizing: 'border-box',
                borderRight: '1px solid rgba(0, 0, 0, 0.12)',
                position: 'relative',
              },
            }}
          >
            <List>
              <ListItem button>
                <ListItemIcon>
                  <HomeIcon />
                </ListItemIcon>
                <ListItemText primary="Home" />
              </ListItem>
              <ListItem button>
                <ListItemIcon>
                  <ExploreIcon />
                </ListItemIcon>
                <ListItemText primary="Explore" />
              </ListItem>
              <ListItem button>
                <ListItemIcon>
                  <SubscriptionsIcon />
                </ListItemIcon>
                <ListItemText primary="Subscriptions" />
              </ListItem>
            </List>
            <Divider />
            <List>
              <ListItem button>
                <ListItemIcon>
                  <VideoLibraryIcon />
                </ListItemIcon>
                <ListItemText primary="Library" />
              </ListItem>
              <ListItem button>
                <ListItemIcon>
                  <HistoryIcon />
                </ListItemIcon>
                <ListItemText primary="History" />
              </ListItem>
              <ListItem button selected={showSummaryPanel} onClick={() => setShowSummaryPanel(!showSummaryPanel)}>
                <ListItemIcon>
                  <SummarizeIcon color={showSummaryPanel ? "primary" : "inherit"} />
                </ListItemIcon>
                <ListItemText primary="Smart Summary" />
              </ListItem>
            </List>
          </Drawer>

          {/* Main content */}
          <Box sx={{ flex: 1, p: 3, overflow: 'auto' }}>
            {selectedVideo ? (
              <Grid container spacing={2}>
                <Grid item xs={12} md={showSummaryPanel ? 8 : 12}>
                  <VideoPlayer videoId={selectedVideo.id} />
                  <Box sx={{ mt: 2 }}>
                    <h2>{selectedVideo.title}</h2>
                    <p>{selectedVideo.views} • {selectedVideo.timestamp}</p>
                    <p>{selectedVideo.channel}</p>
                  </Box>

                  {/* Related Videos */}
                  <RelatedVideos 
                    videos={videos.filter(v => v.id !== selectedVideo.id)} 
                    onVideoSelect={handleVideoSelect} 
                  />
                </Grid>

                {showSummaryPanel && (
                  <Grid item xs={12} md={4}>
                    {loading ? (
                      <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
                        <CircularProgress />
                      </Box>
                    ) : (
                      <Box>
                        <Box sx={{ display: 'flex', mb: 2, borderBottom: '1px solid rgba(0, 0, 0, 0.12)' }}>
                          <Box 
                            onClick={() => setActiveTab('summary')}
                            sx={{ 
                              flex: 1, 
                              p: 1, 
                              textAlign: 'center', 
                              cursor: 'pointer',
                              borderBottom: activeTab === 'summary' ? '2px solid #FF0000' : 'none',
                              fontWeight: activeTab === 'summary' ? 'bold' : 'normal'
                            }}
                          >
                            Summary
                          </Box>
                          <Box 
                            onClick={() => setActiveTab('notes')}
                            sx={{ 
                              flex: 1, 
                              p: 1, 
                              textAlign: 'center', 
                              cursor: 'pointer',
                              borderBottom: activeTab === 'notes' ? '2px solid #FF0000' : 'none',
                              fontWeight: activeTab === 'notes' ? 'bold' : 'normal'
                            }}
                          >
                            Notes
                          </Box>
                        </Box>

                        {activeTab === 'summary' && summary ? (
                          <SummaryDisplay summary={summary} onTimeClick={handleTimeClick} />
                        ) : activeTab === 'summary' && !summary ? (
                          <Box sx={{ p: 2, textAlign: 'center' }}>
                            <p>No summary available yet. Click the "Generate Summary" button in the header to create one.</p>
                          </Box>
                        ) : null}

                        {activeTab === 'notes' && notes ? (
                          <NotesDisplay notes={notes} />
                        ) : activeTab === 'notes' && !summary ? (
                          <Box sx={{ p: 2, textAlign: 'center' }}>
                            <p>No notes available yet. Click the "Generate Summary" button in the header to create notes.</p>
                          </Box>
                        ) : null}
                      </Box>
                    )}
                  </Grid>
                )}
              </Grid>
            ) : (
              <Grid container spacing={2}>
                {videos.map((video) => (
                  <Grid item xs={12} sm={6} md={4} lg={3} key={video.id}>
                    <VideoCard video={video} onVideoSelect={() => handleVideoSelect(video)} />
                  </Grid>
                ))}
              </Grid>
            )}
          </Box>
        </Box>
      </Box>
    </ThemeProvider>
  );
}

export default App;
